def control(obs):
    h = obs.get('hitch_deg', 0.0)
    status = obs.get('status')
    # First recover forward out of the contact, then reverse cautiously.
    if status == 'PINNED' or obs.get('motion', {}).get('hold_s', 0) > 0:
        return (0.0, 0.0, -23.0)
    # Apply a brief forward pull to release the rail, then return to reverse.
    if obs.get('progress', {}).get('covered', 0) < 9.8:
        return (0.0, 0.8, -23.0)
    steer = max(-12.0, min(12.0, 1.1*h))
    return (steer, -0.35, -23.0)

