def control(obs):
    h = obs.get('hitch_deg', 0.0)
    # Follow the trailer's swing while reversing; limit steering for smooth correction.
    steer = max(-35.0, min(35.0, 2.0 * h))
    # Slow down as the hitch angle grows; pull forward to recover before it becomes severe.
    if abs(h) > 45.0:
        return (-25.0 if h > 0 else 25.0, 0.45)
    speed = -0.38 if abs(h) < 20.0 else -0.24
    look = 0.0
    return (steer, speed, look)

